// Packs Codex's Library builder (library/build_library.py + BUILDER.md) into
// functions/_builder_files.js, so the server can hand it to Astra when an item
// is created with AI (functions/_astra.js). The builder itself is never
// published as a web page. Run by tools/stage-deploy.mjs and tools/dev-server.mjs;
// the generated file is not kept in the project (.gitignore).
import fs from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const FILES = ["build_library.py", "BUILDER.md"];

export async function bundleBuilder() {
  const files = {};
  for (const name of FILES) files[name] = await fs.readFile(path.join(ROOT, "library", name), "utf8");
  const out = path.join(ROOT, "functions", "_builder_files.js");
  await fs.writeFile(out, `// Generated by tools/bundle-builder.mjs from library/. Don't edit.\nexport default ${JSON.stringify(files)};\n`);
  return out;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) console.log("Wrote", await bundleBuilder());
